<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {Layers3,ArrowUpRight,Copy,Download,Menu,X} from 'lucide-vue-next'
import {api,copy,action,type Row} from '../lib'
const spec=ref<Row>({}),error=ref(''),lang=ref('curl'),mobile=ref(false),origin=location.origin
const operations=computed(()=>Object.entries(spec.value.paths||{}).flatMap(([path,v])=>Object.entries(v as Row).map(([method,op])=>({path,method,op,id:(op as Row).operationId}))))
const states:Row={draft:'仅保存方案，不会执行付款',queued:'等待调度',processing:'正在办理',awaiting_payment:'结账链接已生成，未付款',succeeded:'已结束；订阅订单还须查看付款、生效、续费各自结果',failed:'办理未完成',cancelled:'已撤回或已停止；不等于银行退款',review:'结果待核实，停止重复提交'}
function schema(v:Row):Row{return v?.$ref?{...spec.value.components?.schemas?.[v.$ref.split('/').at(-1)],...v}:v||{}}
function fields(v:Row,prefix=''):Row[]{const s=schema(v);return Object.entries(s.properties||{}).flatMap(([key,value])=>{const f=value as Row,name=prefix+key,row={...schema(f),...f,name,required:s.required?.includes(key),nested:!!prefix};const children=f.properties?fields(f,name+'.'):f.items?.properties?fields(f.items,name+'[].'):[];return [row,...children]})}
function type(v:Row){if(v.anyOf)return v.anyOf.map((x:Row)=>type(x)).join(' / ');return v.$ref?v.$ref.split('/').at(-1):v.const!==undefined?JSON.stringify(v.const):v.enum?v.enum.join(' / '):Array.isArray(v.type)?v.type.join(' / '):v.type||'object'}
function sample(x:Row){const body=x.op.requestBody?.content?.['application/json']?.example;let url=origin+x.path.replace('{id}','ORDER_ID');const query=(x.op.parameters||[]).filter((p:Row)=>p.in==='query'&&p.required);if(query.length)url+='?'+query.map((p:Row)=>p.name+'='+encodeURIComponent(p.example||'VALUE')).join('&');const headers:Row={Authorization:'Bearer YOUR_XUPAY_KEY'};if(body)headers['Content-Type']='application/json';if(x.op.parameters?.some((p:Row)=>p.in==='header'))headers['Idempotency-Key']='subscription_20261027_001';if(lang.value==='python')return `import os\nimport json\nimport requests\n\nheaders = ${JSON.stringify(headers,null,2).replace('"Bearer YOUR_XUPAY_KEY"','"Bearer " + os.environ["XUPAY_API_KEY"]')}\n${body?'payload = '+'json.loads('+JSON.stringify(JSON.stringify(body))+')'+'\n':''}response = requests.${x.method}(\n    ${JSON.stringify(url)}, headers=headers, ${body?'json=payload, ':''}timeout=30\n)\nresponse.raise_for_status()\nprint(response.json())`;if(lang.value==='node')return `const response = await fetch(${JSON.stringify(url)}, {\n  method: ${JSON.stringify(x.method.toUpperCase())},\n  headers: ${JSON.stringify(headers,null,2).replace('"Bearer YOUR_XUPAY_KEY"','"Bearer " + process.env.XUPAY_API_KEY')}${body?',\n  body: JSON.stringify('+JSON.stringify(body,null,2)+')':''}\n});\nconst result = await response.json();\nif (!response.ok) throw new Error(result.error);\nconsole.log(result);`;return `curl --fail-with-body '${url}' \\\n  -X ${x.method.toUpperCase()} \\\n  `+Object.entries(headers).map(([k,v])=>`-H '${k}: ${v}'`).join(' \\\n  ')+(body?` \\\n  -d '${JSON.stringify(body,null,2)}'`:'')}
onMounted(async()=>{try{spec.value=await api('/openapi.json')}catch(e){error.value=(e as Error).message}})
</script>
<template><div class="api-docs"><button class="docs-menu-toggle icon-btn bordered" @click="mobile=!mobile" aria-label="文档菜单"><Menu :size="20"/></button><aside class="docs-sidebar" :class="{open:mobile}"><a href="/#/home" class="brand"><span class="brand-icon"><Layers3 :size="23"/></span><b>序付<small>DEVELOPERS</small></b></a><button class="icon-btn docs-close" @click="mobile=false" aria-label="收起文档菜单"><X/></button><p class="eyebrow">接入指引</p><a href="/docs#start" @click="mobile=false">快速开始</a><a href="/docs#auth" @click="mobile=false">鉴权与安全</a><a href="/docs#results" @click="mobile=false">提交与结果判断</a><p class="eyebrow">平台 API</p><a v-for="x in operations" :key="x.id" :href="'/docs#'+x.id" @click="mobile=false"><span :class="['method',x.method]">{{x.method.toUpperCase()}}</span>{{x.op.summary}}</a><p class="eyebrow">参考</p><a href="/docs#fields" @click="mobile=false">Session 与订单字段</a><a href="/docs#states" @click="mobile=false">状态与重试</a><a href="/docs#errors" @click="mobile=false">错误处理</a><a href="/api/openapi.json" download="xupay-openapi.json"><Download :size="14"/>OpenAPI 3.1</a><a href="/#/keys">返回开发接入<ArrowUpRight :size="14"/></a></aside><main class="docs-main"><div v-if="error" class="alert danger">{{error}}</div><section id="start" class="docs-intro"><span class="eyebrow">XUPAY / INTEGRATION GUIDE</span><h1>把服务，接入你的工作流。</h1><p>清晰的账户、会员与订单接口。请求只发往序付，业务进度通过序付查询。</p><div class="docs-base"><code>{{origin}}</code><button class="text-btn" @click="action(()=>copy(origin))"><Copy :size="15"/>复制基础地址</button></div><div class="callout">当前版本 {{spec.info?.version}}：支持生成结账链接或自动办理订阅。按所需业务提交套餐、地区及账号资料。订阅办理一次提交后自动付款并按选择处理续费，不返回结账链接；仅生成链接的订单不会自动付款。提链不扣费，订阅受理冻结服务费，付款成功后结算。</div><div class="docs-steps"><span>01 创建 API 密钥</span><span>02 查询报价与余额</span><span>03 识别 Session</span><span>04 提交并查询结果</span></div></section><section id="auth" class="panel docs-section"><h2>鉴权与数据约定</h2><p>本文业务接口均要求 <code>Authorization: Bearer YOUR_XUPAY_KEY</code>。密钥只能访问所属账户的数据。密钥仅创建时显示一次，撤销后立即失效。</p><p>平台服务费金额使用整数分：<b>100 分 = 1 R</b>。银行卡付款 amount 使用对应币种最小单位，JPY 为整数日元。会员等级和报价由服务器计算；账户专属单价优先，历史订单保留创建时的价格快照。</p><p>请从你的服务端调用，不把密钥、兑换码、Session 或银行卡放在 URL 和日志里。当前不开放跨域浏览器调用；不要在浏览器前端嵌入长期 API 密钥。</p><p>接口按账户限流（默认每分钟 120 次）；创建订单默认每分钟 5 次，兑换每分钟 10 次，Session 检查每分钟 20 次。实际额度以服务当前限制为准。遇到 429 请退避重试；如果响应包含 Retry-After，优先遵循该值。</p></section>
<section id="results" class="panel docs-section"><h2>提交与结果判断</h2><p>自动办理订阅时，提交 <code>workflow=subscription</code>、套餐、地区、完整 Session、获授权银行卡及 <code>keep_renewal</code>。返回订单编号后查询订单进度，无需另行调用付款准备或确认。只需要结账链接时提交 <code>workflow=checkout</code> 和 <code>prepare=true</code>；不自动付款。</p><p>服务费报价使用 R，银行卡订阅金额使用订阅币种。<code>payment.amount</code> 是最近保存的报价，可能因税费更新而变化；失败订单可能保留旧报价。<code>charged_amount</code> 有值时才展示对应实收金额，为 null 不代表未付款。</p><div class="docs-table"><table><thead><tr><th>要判断的结果</th><th>读取字段</th><th>确认条件</th></tr></thead><tbody><tr><td>付款成功</td><td>payment.state</td><td>succeeded</td></tr><tr><td>订阅生效且套餐匹配</td><td>order.activation</td><td>active</td></tr><tr><td>自动续费已关闭</td><td>order.renewal</td><td>disabled；kept 表示按要求保留</td></tr></tbody></table></div><p>HTTP 200/202、accepted=true 和过程日志完成只表示请求处理或受理结果，不能代替上述业务状态。付款成功但生效或续费未完成时，继续处理原订单，不要重新提交订阅。</p><p>遇到 <code>action_required</code> 或 <code>review</code>，先查订单详情。<code>automatic_running=true</code> 时等待自动处理；<code>can_check</code> 有返回时按其值申请核实，缺省时可对上述待处理状态尝试核实，以接口受理结果为准。仍需验证或授权失效时联系服务支持。</p></section>
<section v-for="x in operations" :key="x.id" :id="x.id" class="panel docs-section"><div class="endpoint"><b :class="x.method">{{x.method.toUpperCase()}}</b><code>{{x.path}}</code></div><h2>{{x.op.summary}}</h2><p>{{x.op.description}}</p><div v-if="x.op.parameters?.length" class="docs-table"><table><thead><tr><th>参数</th><th>位置</th><th>要求</th><th>说明</th></tr></thead><tbody><tr v-for="p in x.op.parameters" :key="p.name"><td><code>{{p.name}}</code></td><td>{{p.in}}</td><td>{{p.required?'必填':'可选'}}</td><td>{{p.description||p.example||''}} {{p.schema.minLength?'长度 '+p.schema.minLength+'～'+p.schema.maxLength:''}}</td></tr></tbody></table></div><div v-if="x.op.requestBody" class="docs-table"><table><thead><tr><th>JSON 字段</th><th>类型</th><th>要求</th><th>说明</th></tr></thead><tbody><tr v-for="f in fields(x.op.requestBody.content['application/json'].schema)" :key="f.name"><td><code>{{f.name}}</code></td><td>{{type(f)}}</td><td>{{f.required?(f.nested?'提供父字段时必填':'必填'):'可选'}}</td><td>{{f.description||'详见下方字段说明'}}</td></tr></tbody></table></div><div class="section-heading"><div class="tabs"><button v-for="l in ['curl','node','python']" :key="l" :class="{active:lang===l}" @click="lang=l">{{({curl:'cURL',node:'Node.js',python:'Python'} as Row)[l]}}</button></div><button class="text-btn" @click="action(()=>copy(sample(x)))"><Copy :size="14"/>复制示例</button></div><pre>{{sample(x)}}</pre><details><summary>查看响应字段和示例</summary><div v-for="(response,code) in x.op.responses" :key="code"><h4>HTTP {{code}} · {{(response as Row).description}}</h4><div class="docs-table" v-if="fields((response as Row).content?.['application/json']?.schema).length"><table><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr v-for="f in fields((response as Row).content?.['application/json']?.schema)" :key="f.name"><td>{{f.name}}</td><td>{{type(f)}}</td><td>{{f.description||'详见完整字段说明'}}</td></tr></tbody></table></div></div><pre>{{JSON.stringify((x.op.responses['200']||x.op.responses['202'])?.content?.['application/json']?.example||{accepted:true},null,2)}}</pre></details></section>
<section id="fields" class="panel docs-section"><h2>完整字段说明</h2><p>字段名中的点表示嵌套对象，[] 表示数组元素；引用类型可在本节展开对应名称查看。</p><p>示例 Session 的令牌是占位符。实际请求应使用你获授权账号刚获取的完整 Session；Session 检查接口只做格式与有效期检查；订单实际办理还会校验账号状态。请提供最新完整 Session；若提示凭据不完整或已过期，请重新获取后再提交。</p><details v-for="(s,name) in spec.components?.schemas" :key="name"><summary>{{name}}</summary><div class="docs-table"><table><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr v-for="f in fields(s)" :key="f.name"><td>{{f.name}}</td><td>{{type(f)}}</td><td>{{f.description||'—'}}</td></tr></tbody></table></div></details></section><section id="states" class="panel docs-section"><h2>订单状态与重试</h2><div class="docs-table"><table><tbody><tr v-for="(label,state) in states" :key="state"><td><code>{{state}}</code></td><td>{{label}}</td></tr></tbody></table></div><p>草稿无需轮询。排队和办理中的订单建议至少每 5 秒查询；automatic_running=true 时继续低频查询。结果成功、失败、已停止或需人工处理时结束自动轮询。订阅订单需同时读取 payment.state、order.activation、order.renewal：付款成功但生效或续费待核实时，不可再次付款，联系服务支持继续核实。仅生成链接时，建议提交最新完整 Session。workflow=link 且 awaiting_payment 表示链接已生成，无需继续轮询；历史单独付款订单仍须查看付款状态。网络超时重试创建操作必须复用原 Idempotency-Key，不可更换标识重复提交。</p></section><section id="errors" class="panel docs-section"><h2>错误状态</h2><p>失败返回 <code>{"error":"中文错误原因"}</code>，按 HTTP 状态处理，不依赖中文文案进行分支判断。</p><div class="docs-table"><table><tbody><tr v-for="(v,k) in {400:'检查参数、Session 有效期或兑换码状态',401:'重新创建有效密钥，确认账户可用',403:'密钥没有相应权限，或请求来源不被允许',404:'订单不存在或不属于当前账户',409:'幂等标识内容不同，或订单状态冲突；先查原单',429:'触发限流，遵循 Retry-After 并退避重试',500:'暂时失败；先查原单，创建重试沿用原幂等键',503:'任务暂不可用；先核实原单，避免重复提交'}" :key="k"><td><code>{{k}}</code></td><td>{{v}}</td></tr></tbody></table></div></section></main></div></template>
